from html import escape
CSS='''<style id="dore2-canvas-style">[data-d2-node]{cursor:move;touch-action:none}[data-d2-node].d2-selected{outline:1px solid #8c6818!important;outline-offset:2px}.d2-h{position:absolute;width:9px;height:9px;border:1px solid #fff;background:#8c6818;box-shadow:0 0 0 1px #5d4715;z-index:9999}.d2-h[data-dir=n]{top:-6px;left:50%;cursor:ns-resize}.d2-h[data-dir=s]{bottom:-6px;left:50%;cursor:ns-resize}.d2-h[data-dir=e]{right:-6px;top:50%;cursor:ew-resize}.d2-h[data-dir=w]{left:-6px;top:50%;cursor:ew-resize}.d2-h[data-dir=nw]{left:-6px;top:-6px;cursor:nwse-resize}.d2-h[data-dir=ne]{right:-6px;top:-6px;cursor:nesw-resize}.d2-h[data-dir=sw]{left:-6px;bottom:-6px;cursor:nesw-resize}.d2-h[data-dir=se]{right:-6px;bottom:-6px;cursor:nwse-resize}.d2-guide{position:absolute;pointer-events:none;z-index:9998;background:rgba(140,104,24,.72);display:none}.d2-gx{top:0;bottom:0;width:1px}.d2-gy{left:0;right:0;height:1px}.d2-dist{position:absolute;display:none;z-index:9999;padding:2px 4px;background:#8c6818;color:#fff;font:9px ui-monospace,monospace;pointer-events:none}.d2-marquee,.d2-bounds{position:absolute;pointer-events:none;z-index:9997;border:1px solid #8c6818;background:rgba(206,189,116,.07);display:none}.d2-tools{position:absolute;z-index:10000;display:none;gap:2px;padding:4px;background:#252525;box-shadow:0 3px 12px #0003;white-space:nowrap}.d2-tools button{border:0;background:#fff;color:#252525;padding:5px 7px;font:10px ui-monospace,monospace;cursor:pointer}.d2-tools button:hover{background:#CEBD74}</style>'''
JS=r'''<script id="dore2-canvas-js">(()=>{const PAGE=document.body.dataset.d2Page,REV=()=>Number(document.body.dataset.d2Revision||0),C=document.querySelector('.canvas');if(!C||!PAGE)return;let S=[],G=null,M=null;const make=c=>{let e=document.createElement('i');e.className=c;C.append(e);return e},GX=make('d2-guide d2-gx'),GY=make('d2-guide d2-gy'),DL=make('d2-dist'),MQ=make('d2-marquee'),B=make('d2-bounds'),T=document.createElement('div');T.className='d2-tools';T.innerHTML='<button data-align="left">L</button><button data-align="center">C</button><button data-align="right">R</button><button data-align="top">T</button><button data-align="middle">M</button><button data-align="bottom">B</button><button data-dist="horizontal">H↔</button><button data-dist="vertical">V↕</button>';C.append(T);const N=()=>[...C.querySelectorAll('[data-d2-node]')],num=(e,k)=>parseFloat(e.dataset[k]||0),sc=()=>C.getBoundingClientRect().width/C.offsetWidth||1,R=e=>({x:num(e,'x'),y:num(e,'y'),w:num(e,'w')||e.offsetWidth,h:num(e,'h')||e.offsetHeight}),U=a=>{let q=a.map(R),x=Math.min(...q.map(v=>v.x)),y=Math.min(...q.map(v=>v.y)),r=Math.max(...q.map(v=>v.x+v.w)),b=Math.max(...q.map(v=>v.y+v.h));return{x,y,w:r-x,h:b-y}};function paint(){N().forEach(n=>n.classList.toggle('d2-selected',S.includes(n)));C.querySelectorAll('.d2-h').forEach(x=>x.remove());if(S.length===1)'n ne e se s sw w nw'.split(' ').forEach(d=>{let h=document.createElement('b');h.className='d2-h';h.dataset.dir=d;S[0].append(h)});if(!S.length){B.style.display=T.style.display='none';return}let u=U(S);Object.assign(B.style,{display:'block',left:u.x+'px',top:u.y+'px',width:u.w+'px',height:u.h+'px'});Object.assign(T.style,{display:'flex',left:Math.max(0,u.x)+'px',top:Math.max(0,u.y-36)+'px'});parent.postMessage({type:'dore-selection',page_id:PAGE,ids:S.map(x=>x.dataset.id)},'*');if(S.length===1)parent.postMessage({type:'dore-select',page_id:PAGE,id:S[0].dataset.id,field:'text',value:S[0].innerText},'*')}const set=a=>{S=[...new Set(a)];paint()},emit=c=>parent.postMessage({type:'dore2-command',expected_revision:REV(),command:c},'*'),hide=()=>GX.style.display=GY.style.display=DL.style.display='none';function snap(x,y,w,h,ignore){let bestX={d:7,v:x,g:null},bestY={d:7,v:y,g:null},xs=[0,C.offsetWidth/2,C.offsetWidth],ys=[0,C.offsetHeight/2,C.offsetHeight];N().filter(n=>!ignore.includes(n)).forEach(n=>{let r=R(n);xs.push(r.x,r.x+r.w/2,r.x+r.w);ys.push(r.y,r.y+r.h/2,r.y+r.h)});[x,x+w/2,x+w].forEach((p,i)=>xs.forEach(g=>{let d=Math.abs(p-g);if(d<bestX.d)bestX={d,v:x+(g-p),g}}));[y,y+h/2,y+h].forEach((p,i)=>ys.forEach(g=>{let d=Math.abs(p-g);if(d<bestY.d)bestY={d,v:y+(g-p),g}}));if(bestX.g!==null){GX.style.display='block';GX.style.left=bestX.g+'px'}else GX.style.display='none';if(bestY.g!==null){GY.style.display='block';GY.style.top=bestY.g+'px'}else GY.style.display='none';if(bestX.g!==null||bestY.g!==null){DL.style.display='block';DL.textContent=Math.round(Math.min(bestX.d,bestY.d))+' px';DL.style.left=(bestX.v+w+5)+'px';DL.style.top=(bestY.v-16)+'px'}else DL.style.display='none';return{x:bestX.v,y:bestY.v}}T.onpointerdown=e=>e.stopPropagation();T.onclick=e=>{let ids=S.map(n=>n.dataset.id),a=e.target.dataset.align,d=e.target.dataset.dist;if(a&&ids.length>1)emit({op:'node.align',page_id:PAGE,ids,edge:a});if(d&&ids.length>2)emit({op:'node.distribute',page_id:PAGE,ids,axis:d})};C.onpointerdown=e=>{if(e.target.closest('.d2-tools'))return;let el=e.target.closest('[data-d2-node]'),s=sc();if(!el){let cr=C.getBoundingClientRect(),x=(e.clientX-cr.left)/s,y=(e.clientY-cr.top)/s;M={id:e.pointerId,x,y,cx:x,cy:y,add:e.shiftKey};MQ.style.display='block';Object.assign(MQ.style,{left:x+'px',top:y+'px',width:0,height:0});C.setPointerCapture(e.pointerId);if(!e.shiftKey)set([]);return}e.preventDefault();if(e.shiftKey){set(S.includes(el)?S.filter(x=>x!==el):S.concat(el));return}if(!S.includes(el))set([el]);let dir=e.target.dataset.dir||'',rs=S.map(n=>({el:n,...R(n)})),u=U(S);G={id:e.pointerId,sx:e.clientX,sy:e.clientY,s,dir,rs,u};el.setPointerCapture(e.pointerId)};C.onpointermove=e=>{if(M&&e.pointerId===M.id){let cr=C.getBoundingClientRect(),s=sc();M.cx=(e.clientX-cr.left)/s;M.cy=(e.clientY-cr.top)/s;let x=Math.min(M.x,M.cx),y=Math.min(M.y,M.cy);Object.assign(MQ.style,{left:x+'px',top:y+'px',width:Math.abs(M.cx-M.x)+'px',height:Math.abs(M.cy-M.y)+'px'});return}if(!G||e.pointerId!==G.id)return;let dx=(e.clientX-G.sx)/G.s,dy=(e.clientY-G.sy)/G.s;if(!G.dir){let q=snap(G.u.x+dx,G.u.y+dy,G.u.w,G.u.h,S),ox=q.x-G.u.x,oy=q.y-G.u.y;G.rs.forEach(r=>{r.el.style.left=r.x+ox+'px';r.el.style.top=r.y+oy+'px';r.p={x:r.x+ox,y:r.y+oy}})}else if(S.length===1){let r=G.rs[0],x=r.x,y=r.y,w=r.w,h=r.h,d=G.dir;if(d.includes('e'))w=Math.max(12,r.w+dx);if(d.includes('s'))h=Math.max(12,r.h+dy);if(d.includes('w')){w=Math.max(12,r.w-dx);x=r.x+r.w-w}if(d.includes('n')){h=Math.max(12,r.h-dy);y=r.y+r.h-h}Object.assign(r.el.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});r.p={x,y,w,h}}paint()};C.onpointerup=e=>{if(M&&e.pointerId===M.id){let x=Math.min(M.x,M.cx),y=Math.min(M.y,M.cy),r=Math.max(M.x,M.cx),b=Math.max(M.y,M.cy),hit=N().filter(n=>{let q=R(n);return q.x<r&&q.x+q.w>x&&q.y<b&&q.y+q.h>y});set(M.add?S.concat(hit):hit);MQ.style.display='none';M=null;return}if(!G||e.pointerId!==G.id)return;hide();let ps=G.rs.filter(r=>r.p).map(r=>({id:r.el.dataset.id,patch:r.p}));if(ps.length)emit(ps.length===1?{op:'node.patch',page_id:PAGE,id:ps[0].id,patch:ps[0].patch}:{op:'node.patch_many',page_id:PAGE,patches:ps});G=null};parent.postMessage({type:'dore2-direct-ready',page_id:PAGE,revision:REV()},'*')})()</script>'''
def augment(html,page_id,revision):
    html=html.replace('</head>',CSS+'</head>',1).replace('<body ',f'<body data-d2-page="{escape(str(page_id))}" data-d2-revision="{int(revision)}" ',1)
    return html.replace('</body>',JS+'</body>',1)
